    "content": "欧盟委员会接受赛诺菲提交的整改承诺，就此了结针对其Efluelda流感疫苗营销活动的反垄断调查。欧盟反垄断机构表示，已采纳法国药企赛诺菲提出的整改方案，以此结案，结束针对该企业一款流感疫苗营销推广行为的竞争调查。欧盟委员会是欧盟的执行机构，同时也是竞争规则执法机关。委员会周三表示，赛诺菲提出方案，将纠正其过往宣传言论对澳大利亚CSL公司的竞品流感疫苗造成的潜在不良影响，该方案可以消除监管方面的顾虑。委员会补充，上述承诺将对赛诺菲产生法律约束力。（新浪财经）"
