    "title": "石大胜华：预计2026年前三季度净利润5.4亿元到5.8亿元，同比扭亏为盈",
    "link": "https://36kr.com/newsflashes/4025547894722435?f=rss",
    "pub_date": "2026-10-14 18:07:56",
    "author": "",
    "description": "36氪获悉，石大胜华公告，预计2026年前三季度归属于上市公司股东的净利润5.4亿元到5.8亿元，2025年同期亏损6220.18万元，同比扭亏为盈；扣除非经常性损益后的净利润5.45亿元到5.84亿元，2025年同期亏损6602.65万元，同比扭亏为盈。业绩增长主要受下游动力电池及储能电池需求快速增长、核心产品市场价格较上年同期显著上涨等因素带动。",
    "content": "36氪获悉，石大胜华公告，预计2026年前三季度归属于上市公司股东的净利润5.4亿元到5.8亿元，2025年同期亏损6220.18万元，同比扭亏为盈；扣除非经常性损益后的净利润5.45亿元到5.84亿元，2025年同期亏损6602.65万元，同比扭亏为盈。业绩增长主要受下游动力电池及储能电池需求快速增长、核心产品市场价格较上年同期显著上涨等因素带动。"
