    "id": "新闻-36氪-https://36kr.com/newsflashes/4025547059171465?f=rss",
    "feed_name": "36氪",
    "category": "新闻",
    "title": "蚂蚁灵波与隆盛唯睿等多家企业达成深度合作，具身机器人加速落地工业物流",
    "link": "https://36kr.com/newsflashes/4025547059171465?f=rss",
    "pub_date": "2026-10-14 18:07:16",
    "author": "",
    "description": "36氪获悉，近日，蚂蚁灵波接连与隆盛科技控股子公司隆盛唯睿、物流装备与解决方案提供商德马科技、德尔股份旗下机器人公司德迩象网等多家智能制造及现代物流企业达成深度战略合作。基于自研的具身原生模型及云端工具链，蚂蚁灵波将携手生态伙伴，共同攻关具身机器人在严苛工业与物流环境下的全新解决方案。",
    "content": "36氪获悉，近日，蚂蚁灵波接连与隆盛科技控股子公司隆盛唯睿、物流装备与解决方案提供商德马科技、德尔股份旗下机器人公司德迩象网等多家智能制造及现代物流企业达成深度战略合作。基于自研的具身原生模型及云端工具链，蚂蚁灵波将携手生态伙伴，共同攻关具身机器人在严苛工业与物流环境下的全新解决方案。"
