    "description": "36氪获悉，武汉天源公告，公司拟与楚雄高新技术产业开发区管理委员会签署合作协议，投资建设“楚雄高新区年产200吨6N/7N级高纯铟及年产100吨磷化铟多晶生产基地项目”，计划总投资约5亿元，其中自有资金约1亿元，银行贷款约4亿元。项目建设工期12个月，主要建设高纯铟、磷化铟多晶生产线及相关配套设施。公司提示，该项目涉及新领域、新业务，暂无相关技术和人员储备，存在技术验证、原材料供应及市场等多重风险，短期内不会对经营业绩构成重大影响。",
