    "content": "新华社北京10月14日电 “北溪”爆炸事件的乌克兰籍嫌疑人谢尔盖·库兹涅佐夫将于14日在德国首次接受庭审。 2022年9月26日，连通俄罗斯和德国以及其他欧洲国家的波罗的海海底输气管道“北溪-1”和“北溪-2”经过丹麦和瑞典附近海域的部分发生剧烈爆炸，大量天然气泄漏。调查发现，4条管道中的3条发生泄漏，疑遭人为破坏。德国检方认为，库兹涅佐夫及其所属团伙涉嫌在丹麦博恩霍尔姆岛附近海域潜水安装多枚炸弹，以炸毁“北溪”管道。 这张丹麦国防部2022年9月27日发布的航拍照片显示的是一处“北溪”天然气管道泄漏点。新华社发（…"
