    "content": "新华社北京10月14日电（记者赵博、许晓静、谈昦玄）国务院台办发言人陈斌华14日在例行新闻发布会上表示，2025年6月，国务院台办宣布对“台独”顽固分子沈伯洋之父沈土城担任负责人的兆亿有限公司实施惩戒。经查，沈土城为躲避制裁，以另一家公司VWAY名义，继续与大陆相关企业进行贸易往来与业务合作，从中谋取经济利益。沈伯洋一边鼓噪“反中抗中”、阻碍两岸交流合作，一边会同亲属想方设法从大陆赚钱，丑陋行径令人不齿。大陆方面决不允许“台独”顽固分子关联企业在大陆谋利，决定对VWAY公司实施惩戒，采取禁止其与大陆组织、企业、个人…"
