    "content": "10月13日，记者随“活力中国调研行”采访团走进位于广西南宁的中国—东盟商品汇聚中心。走进汇聚中心，新加坡肉骨茶、泰国咖喱、马来西亚榴莲等特色商品琳琅满目，多国风情在廊道间流转。 中国—东盟商品汇聚中心联席总经理卢春梅表示，经过4年的运营与发展，该中心已将365天“永不落幕”的中国—东盟博览会由愿景化为现实，持续放大东博会的溢出带动效应。 该中心由中新南宁国际物流中心与中国—东盟博览会秘书处联合打造，设有18个文化主题馆，入驻商品已超过6000种，涵盖食品、日用品、保健品、文旅产品等。到访嘉宾在此可直观感受不同国家…"
