    "content": "新华社北京10月14日电（记者唐诗凝）中国汽车工业协会14日发布声明表示，中欧就混动汽车、电动汽车贸易问题达成共识，有助于稳定双方产业预期，维护汽车产业链供应链稳定畅通。中汽协会愿继续推动行业加强沟通协调，共同维护公平、开放、非歧视的国际贸易环境。 近日，中欧双方秉持相互尊重、平等协商的原则，在贸易投资磋商机制下就混动汽车、电动汽车贸易进行了密集磋商并达成共识。中国汽车工业协会对此高度关注，并对磋商取得的积极成果表示欢迎和支持。 声明指出，当前全球贸易保护主义抬头，国际经贸环境的不确定性明显上升。汽车产业全球化程度…"
