    "description": "台财政事务主管部门10月8日发布的海关进出口贸易初步统计显示，9月台湾对大陆(含香港)出口206.2亿美元，同比增长30.2%；自大陆(含香港)进口135亿美元，同比增长59.1%。尽管民进党当局不断炒作“脱钩断链”，但市场用真实贸易数据给出答案：两岸产业链拆不开、断不了。",
