    "author": "tumk",
    "description": "上一篇发了 LayoutKeeper 之后，有朋友问：恢复窗口位置的工具有好几个，为什么偏偏「连桌面一起恢复」这么难？这篇写写我做这个功能时踩的过程，纯开发日志向。 先说结论：难的不是「移动窗口」，是「知道窗口在哪个桌面」和「让系统允许你把它送回去」。 **第一坑：其他桌面的窗口，系统默认不给你看。** 辅助功能 API （ AX ）只能拿到当前桌面的窗口列表。想枚举外接屏上其他桌面的窗口，得拿公开的窗口列表先算出候选，再用远程元素令牌…",
    "content": "上一篇发了 LayoutKeeper 之后，有朋友问：恢复窗口位置的工具有好几个，为什么偏偏「连桌面一起恢复」这么难？这篇写写我做这个功能时踩的过程，纯开发日志向。 先说结论：难的不是「移动窗口」，是「知道窗口在哪个桌面」和「让系统允许你把它送回去」。 **第一坑：其他桌面的窗口，系统默认不给你看。** 辅助功能 API （ AX ）只能拿到当前桌面的窗口列表。想枚举外接屏上其他桌面的窗口，得拿公开的窗口列表先算出候选，再用远程元素令牌把窗口找回来，而且要校验进程和窗口编号对得上——校验不过的不动，宁可漏恢复，也不…"
