    "content": "新华社北京10月14日电（记者赵博、尚昊）针对台湾艺人蔡康永现身民进党台北市长参选人沈伯洋竞选总部成立大会，国务院台办发言人陈斌华14日在例行新闻发布会上答问表示，我们始终尊重和保障台湾同胞正当的言论与表达自由，但在大是大非问题上，没有任何模糊空间。维护统一、反对“台独”是全体中国人民的共同意志，任何人、任何势力都不能一边赚取大陆发展红利，一边与“台独”分裂势力勾连纠缠，做“两面人”。 他指出，台湾是中国领土不可分割的一部分，坚持一个中国原则是国际社会的普遍共识，也是两岸同胞共同的政治基础。“台独”顽固分子沈伯洋的…"
