    "content": "新华社香港10月14日电（记者刘媛媛）记者14日从香港保险业监管局了解到，中国人民财产保险股份有限公司在香港发行首宗“侧挂车”形式的保险相连证券，发行总额为1200万美元（约合9400万港元），以比例再保险方式为中国内地的海上风电保险业务提供保障。 香港特区政府财经事务及库务局局长许正宇表示，此举可发挥保险相连证券等多层次风险转移和分担机制的叠加效应，从而巩固香港作为区域乃至全球巨灾及专项风险管理枢纽的战略功能。 “侧挂车”是一种保险相连证券结构，投资者透过该结构向特定保险或再保险组合提供资本。一般而言，“侧挂车”…"
